 <!DOCTYPE html>
 <html lang="en">
 <head>
   <meta charset="UTF-8" />
   <meta name="viewport" content="width=device-width, initial-scale=1.0" />
   <title>Support Contact Form</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --card: #ffffff;
       --text: #152033;
       --muted: #5f6b85;
       --border: #d7deea;
       --accent: #2457ff;
       --accent-dark: #1c46cf;
       --error: #c62828;
       --shadow: 0 24px 60px rgba(21, 32, 51, 0.10);
