       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top, rgba(36, 87, 255, 0.12), transparent 34%),
         var(--bg);
       min-height: 100vh;
       display: grid;
       place-items: center;
       padding: 32px 16px;
     }

     .page-shell {
       width: min(100%, 720px);
     }

     .support-card {
       background: var(--card);
       border: 1px solid rgba(215, 222, 234, 0.8);
