       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
     }

     h1 {
       margin: 0;
       font-size: clamp(1.8rem, 3vw, 2.4rem);
       line-height: 1.1;
     }

     .subtitle {
       margin: 12px 0 0;
       color: var(--muted);
       max-width: 58ch;
     }

     form {
       padding: 20px 32px 32px;
     }

     .form-grid {
       display: grid;
       gap: 18px;
     }

     .form-field {
       display: grid;
       gap: 8px;
