       box-shadow: 0 18px 34px rgba(36, 87, 255, 0.26);
     }

     .submit-button:focus {
       outline: none;
       box-shadow: 0 0 0 4px rgba(36, 87, 255, 0.16), 0 18px 34px rgba(36, 87, 255, 0.26);
     }

     @media (max-width: 640px) {
       body {
