 </head>
 <body>
   <main class="page-shell">
     <section class="support-card" aria-labelledby="support-title">
       <header class="support-header">
         <p class="eyebrow">Support</p>
         <h1 id="support-title">Contact our team</h1>
         <p class="subtitle">Send us a message and we’ll get back to you as soon as possible.</p>
       </header>

       <form id="support-form" novalidate>
         <div class="form-grid">
           <div class="form-field" data-field="fullName">
             <label for="fullName">Full name</label>
             <input class="field-input" id="fullName" name="fullName" type="text" autocomplete="name" required />
             <span class="field-error" id="fullName-error" aria-live="polite"></span>
           </div>

           <div class="form-field" data-field="email">
             <label for="email">Email address</label>
             <input class="field-input" id="email" name="email" type="email" autocomplete="email" required />
             <span class="field-error" id="email-error" aria-live="polite"></span>
           </div>

           <div class="form-field" data-field="phone">
             <label for="phone">Phone number</label>
             <input
               class="field-input"
               id="phone"
               name="phone"
               type="tel"
               autocomplete="tel"
               placeholder="(555) 123-4567"
               aria-describedby="phone-help phone-error"
             />
             <span class="field-help" id="phone-help">Optional. Use a format like (555) 123-4567 or 555-123-4567.</span>
             <span class="field-error" id="phone-error" aria-live="polite"></span>
           </div>
         </div>

         <div class="actions">
           <button class="submit-button" type="submit">Submit request</button>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById('support-form');
     const fields = {
       fullName: {
         input: document.getElementById('fullName'),
         error: document.getElementById('fullName-error'),
         field: document.querySelector('[data-field="fullName"]'),
       },
       email: {
         input: document.getElementById('email'),
         error: document.getElementById('email-error'),
         field: document.querySelector('[data-field="email"]'),
       },
       phone: {
         input: document.getElementById('phone'),
         error: document.getElementById('phone-error'),
         field: document.querySelector('[data-field="phone"]'),
       },
     };

     const phonePattern = /^(?:\(\d{3}\)\s?\d{3}-\d{4}|\d{3}-\d{3}-\d{4})$/;
     let hasValidated = false;

     function setFieldState(key, message) {
       const { field, error, input } = fields[key];
       const invalid = Boolean(message);

       field.dataset.invalid = invalid ? 'true' : 'false';
       error.textContent = message;
       input.setAttribute('aria-invalid', invalid ? 'true' : 'false');
     }

     function validateField(key) {
       const { input } = fields[key];
       const value = input.value.trim();

       if (key === 'fullName' && !value) return 'Full name is required.';
       if (key === 'email') {
         if (!value) return 'Email address is required.';
         if (!input.validity.valid) return 'Enter a valid email address.';
       }
       if (key === 'phone' && value && !phonePattern.test(value)) {
         return 'Enter a phone number in the expected format.';
       }

       return '';
     }

     function validateForm() {
       let isValid = true;
       for (const key of Object.keys(fields)) {
         const message = validateField(key);
         setFieldState(key, message);
         if (message) isValid = false;
       }
       return isValid;
     }

     form.addEventListener('submit', (event) => {
       hasValidated = true;
       if (!validateForm()) {
         event.preventDefault();
       }
     });

     for (const key of Object.keys(fields)) {
       fields[key].input.addEventListener('input', () => {
         if (!hasValidated) return;
         setFieldState(key, validateField(key));
       });
       fields[key].input.addEventListener('blur', () => {
         if (!hasValidated) return;
         setFieldState(key, validateField(key));
       });
     }
   </script>
